    /**
     * 
     * @param {*} req_object 
     * @param {*} config 
     * @returns 
     */
    async function fetchCausalAnalysis(req_object, config) {
        let _type = "DSC"
        await $.ajax({
            headers: { Accept: "text/html" },
            cache: false,
            url: "causeway/getType",
            type: "GET",
            data: {},
            success: async function (res) {
                _type = res
            },
            error: async function (err) {
                let validityError = err.responseJSON.error
                console.log(`${prefix} ERROR`, err.responseJSON.error)
            },
            complete: async function () {
            }
        })
        let causal_inf_uri = uri + ":" + port + "/causal_inference/" + model_id
        console.log(causal_inf_uri)
        req_object["cwy_type"] = _type
        console.log("fetching causal anlaysis using config: ", config)
        console.log("fetching causal anlaysis using req_object: ", req_object)

        try {
            // aws/host.docker.internal implementation
            return await $.ajax({
                headers: {
                    Accept: "text/html; application/json",
                },
                cache: false,
                url: "causeway/fetchCausalAnalysis",
                type: "POST",
                timeout: 0,
                data: {
                    "model_id": model_id,
                    "req_object": req_object
                },
                success: async function (json) {
                    console.log("at success")
                    pywhy_results[activeWorkspace] = await update_pywhy_info(config.analysis_type, pywhy_results[activeWorkspace], json)
                    RED.notify(config["messages"]["success"], "success")
                    debugMessage(config["messages"]["success"])
                },
                error: async function (err) {
                    console.log("error ajax causeway/fetchCausalAnalysis", err)
                    if (err.hasOwnProperty("responseJSON")) {
                        console.log(err.responseJSON["error"])
                        await enable_buttons()
                        RED.notify(config["messages"]["error"] + " : " + err.responseJSON["error"], "error")
                        debugMessage(config["messages"]["error"] + " : " + err.responseJSON["error"])
                    } else {
                        RED.notify(config["messages"]["error"] + " : " + err.statusText, "error")
                        debugMessage(config["messages"]["error"] + " : " + err.statusText)
                    }
                },
                complete: async function () {
                    return pywhy_results[activeWorkspace]
                }
            })
        } catch (exception) {
            console.log("Fetch causal analysis", exception)
            await enable_buttons()
            throw exception
        }
    }

