    /**
     * Process the result from pywhy
     * @param {*} res 
     * @param {*} getdigraph 
     * @returns 
     */
    async function processPyWhyResult(res, getdigraph, activeWorkspace) {
        let prefix = `[ Processing PyWhy Results ]`
        console.log(`Response at ${prefix} `, res)
        if (res !== undefined) {
            if (res.hasOwnProperty("pywhy_icalingam")) {
                let workspace_id = RED.nodes.id()
                RED.nodes.addWorkspace({
                    id: workspace_id,
                    type: "tab",
                    disabled: false,
                    label: "ICALINGAM",
                    info: "icalingam",
                    env: []
                });
            }
            for await (let node of nodes) {
                // need to access runtime nodes for causeeffect to access edge_strength, intrinsic_effects, causal_mechanisms
                let converted_node = RED.nodes.node(node.id)
                if (node.type === "causeeffect" && node.id !== undefined) {
                    let result = ""
                    if (res.hasOwnProperty("edge_strength")) {
                        if (Object.keys(res["edge_strength"]).length > 0) {
                            result = res["edge_strength"][node.id] !== undefined ? res["edge_strength"][node.id] : undefined
                            result = res["edge_strength"][node.name] !== undefined ? res["edge_strength"][node.name] : result
                            // console.log(`edge strength ${node.name} ${node.id}  PROCESSING PYHWHY RESULT :`, result)
                            converted_node.edgestrength = result
                        }
                    }

                    if (res.hasOwnProperty("intrinsic_effects")) {
                        if (Object.keys(res["intrinsic_effects"]).length > 0) {
                            result = res["intrinsic_effects"][node.id] !== undefined ? res["intrinsic_effects"][node.id] : undefined
                            result = res["intrinsic_effects"][node.name] !== undefined ? res["intrinsic_effects"][node.name] : result
                            // console.log(`intrinisc effects ${node.name} ${node.id}  PROCESSING PYHWHY RESULT :`, result)
                            converted_node.intrinsiceffects = result
                        }
                    }

                    if (res.hasOwnProperty("causal_mechanisms")) {
                        if (Object.keys(res["causal_mechanisms"]).length > 0) {
                            result = res["causal_mechanisms"][node.id] !== undefined ? res["causal_mechanisms"][node.id] : undefined
                            result = res["causal_mechanisms"][node.name] !== undefined ? res["causal_mechanisms"][node.name] : result
                            // console.log(`causal mechanisms ${node.name} ${node.id}  PROCESSING PYHWHY RESULT :`, result)
                            converted_node.causalmechanism = result
                        }
                    }
                    if (res.hasOwnProperty("validate_causal_model")) {
                        for await (let nodeName of Object.keys(res["validate_causal_model"])) {
                            // console.log("nodename ==== convertedn_node.name ", nodeName === converted_node.name)
                            if (nodeName === converted_node.name) {
                                let nodeTests = res["validate_causal_model"][nodeName]
                                converted_node.localmarkovtest = nodeTests["local_markov_test"]
                                converted_node.edgedependencetest = nodeTests["edge_dependence_test"]
                            }
                        }
                    }
                }
            }
            return res
        }
        return {}
    }

    /**
     * 
     * @param {*} _activeWorkspace 
     */
    async function resolvePreviousState(_activeWorkspace) {
        try {
            for await (let node of nodes) {
                if (node.hasOwnProperty("edgestrength")) {
                    let temp = {}
                    if (node.edgestrength !== undefined) {
                        Object.keys(node.edgestrength).forEach(async (key) => {
                            temp[key] = node.edgestrength[key]
                        })
                        _activeWorkspace["edge_strength"] = { ..._activeWorkspace["edge_strength"], [node.id]: temp }
                    }
                }
                if (node.hasOwnProperty("causalmechanism")) {
                    let temp = {}
                    if (node.causalmechanism !== undefined) {
                        Object.keys(node.edgestrength).forEach(async (key) => {
                            temp[key] = node.edgestrength[key]
                        })
                        _activeWorkspace["edge_strength"] = { ..._activeWorkspace["edge_strength"], [node.id]: temp }
                    }
                }
            }
            console.log(_activeWorkspace)
        } catch (exception) {
            throw exception
        }
    }

    /**
     * 
     * @returns 
     */
    async function getPyWhyLinkInfo() {
        let prefix = " [ getPyWhyLinkInfo ] "
        try {
            if (activeWorkspace === 0) {
                return {}
            } else {

                console.log("Requesting Pywhy Link Info")
                let request_data = {
                    "activeWorkspace": activeWorkspace,
                }
                await $.ajax({
                    headers: {
                        Accept: "text/html; application/json",
                    },
                    cache: false,
                    url: "causeway/getPyWhyInfo",
                    type: "POST",
                    data: request_data,
                    success: async function (res) {
                        // console.log("successfully retrieved pywhy link info", res)
                        // retrieve values stored in the database
                        if (nodes === null || nodes === undefined) {
                            await loadNodes()
                        }
                        pywhy_results[activeWorkspace] = { ...pywhy_results[activeWorkspace] }
                        // console.log("ACTIVE WORSKPACE PYWHY RESULTS ", pywhy_results[activeWorkspace])
                        let temp = await processPyWhyResult(res, true, activeWorkspace)
                        pywhy_results[activeWorkspace] = { ...pywhy_results[activeWorkspace], ...temp }
                        // console.log("POSTPROCESS PYWHY RESULTS ", pywhy_results[activeWorkspace])

                    },
                    error: function (error) {
                        console.log("Error response ", error)
                        RED.notify(error.responseText, "error")
                        debugMessage(error.responseText)
                    }
                }).done(() => {
                    return pywhy_results[activeWorkspace]
                }).fail((exception) => {
                    console.log("failed", exception)
                    throw exception
                })
                return pywhy_results[activeWorkspace]
            }
        } catch (exception) {
            console.log("exception @getPyWhyLinkInfo ", exception)
        }
    }


