    async function executeAnalysis(id, message) {
        let button_id = "#fetch-causal-analysis-" + id
        await disable_buttons()
        try {
            await convert_button_to_load(button_id)
            RED.notify(message)
            let strategy = causalStrategyManager.getStrategy(id)
            if (strategy._name === id) {
                let req_object = await strategy.prepare_request()
                console.log("REQUEST OBJECT FOR", req_object)
                let fetch_result = await strategy.fetch(req_object)
                if (fetch_result) {
                    console.log("executeAnalysis  req object ", req_object)
                    await strategy.postprocess(fetch_result)
                }
            }
            await restore_button(button_id)
            await enable_buttons()
            RED.view.redraw()
        } catch (exception) {
            console.log(exception, Object.keys(exception))
            await restore_button(button_id)
            await enable_buttons()
        }
    }


