    /**
     * 
     */
    async function getDataAverages() {
        let _averages = {}
        try {
            // call to api to retrieve average values of data
            _averages = $.ajax({
                headers: {
                    Accept: "text/html",
                    // "Accept-Language": lang,
                },
                cache: false,
                url: "causeawy/getDataAverages",
                type: "GET",
                data: {
                    "activeWorkspace": activeWorkspace,
                    "labels": await loadLabels(),
                },
                success: async function (res) {
                    let _a = {}
                    if (res.hasOwnProperty("averages")) {
                        res["averages"] = JSON.parse(res["averages"])
                        if (typeof res["averages"] === "string") {
                            res["averages"] = JSON.parse(res["averages"])
                        }

                        // update counterfactual analysis container with average values
                        await updateCounterfactualAverageValues(res["averages"])
                    }
                    console.log("response: ", res)
                    RED.settings.set("data-averages", res["averages"])
                    return _a
                },
            }).done(() => {
            }).fail(function (xhr, status, error) {
                console.log("status: ", status);
                console.log("error: ", error);
                RED.notify("[TypeDB] " + error, "error");
                debugMessage("[TypeDB] " + error)
            })
            return _averages
        } catch (exception) {
            RED.notify("Failed to get averages for variables to perform counterfactual analysis ")
            return {}
        }
    }

    /**
     * 
     */
    async function fillCounterfactualAnalysisEditor(nodes, _previous_cfa_values, _intervention) {
        try {
            let _fn = `fillCounterfactualAnalysis`
            // console.log(`${_fn} nodes provided`, nodes)
            // console.log(`${_fn} previous cfa values`, _previous_cfa_values)
            // console.log(`${_fn} new intervention`, _intervention)

            // check context to see if data-averages exists
            let _dataAverageContext = RED.settings.get("data-averages")
            // console.log(`${_fn} context data - average`, _dataAverageContext)

            // add each node to the counterfactual analysis container list item
            let _counterfactual_container = $("#counterfactual-container")
            _counterfactual_container.empty()
            for await (let node of nodes) {
                if (node.type === "causeeffect") {
                    let value = ""
                    if (_dataAverageContext !== undefined) {
                        if (_dataAverageContext.hasOwnProperty(node.name)) {
                            value = _dataAverageContext[node.name]
                        }
                    }
                    if (_previous_cfa_values.hasOwnProperty(node.name)) {
                        value = _previous_cfa_values[node.name]
                    }
                    let _config = {
                        "id": node.id,
                        "name": node.name,
                        "intervene": _intervention,
                        "value": value
                    }
                    if (node.hasOwnProperty("d")) {
                        if (!node.d) {
                            _counterfactual_container.editableList("addItem", _config)
                        }
                    } else {
                        _counterfactual_container.editableList("addItem", _config)
                    }
                    if (node.name === _intervention) {
                        $("#cf-intervention-value").val(_config.value)
                    }
                }
            }
        } catch (exception) {
            console.log("Failed to fill counterfactual analysis container properly due to ", exception.toString())
        }
    }

