    /**
     * 
     * @param {*} previous_id 
     * @param {*} current_id 
     */
    function updateTreatmentSelect(previous_id, current_id, type) {
        try {

            if (type === "treatment") {

                // revert all treatments back to treatment value 
                Object.keys(treatments).forEach(async (trt) => {
                    let node_id = treatments[trt]
                    id_hash = "#_" + node_id
                    d3.select(id_hash).select("rect")
                        .style("stroke", "green")
                        .style("stroke-width", "3")
                        .style("opacity", "0.9")

                })

                // check if the current id is also 
                id_hash = "#_" + $("#model-analysis-outcome").data("prev")
                if (id_hash !== undefined) {
                    d3.select(id_hash).select("rect")
                        .style("stroke", "yellow")
                        .style("stroke-width", "3")
                        .style("opacity", "0.9")
                }

                // update current id to new color 
                id_hash = "#_" + $("#intrinsic_effects-select").data("prev")
                if (id_hash !== undefined) {
                    d3.select(id_hash).select("rect")
                        .style("stroke", "#5D3A9B")
                        .style("stroke-width", "3")
                        .style("opacity", "0.9")
                }
            }

            if (type === "intrinsic-effects") {
                // this scenario doesn't exist
                // if current and previous id are not the same revert the previous selected treatment to original color
                let id_hash = "#_" + previous_id
                if (id_hash !== undefined) {
                    d3.select(id_hash).select("rect")
                        .style("stroke", "gray")
                        .style("stroke-width", "1.25")
                        .style("opacity", "0.9")
                }

                // check if previous_id is treatment value
                Object.keys(treatments).forEach(async (trt) => {
                    let node_id = treatments[trt]
                    id_hash = "#_" + node_id
                    d3.select(id_hash).select("rect")
                        .style("stroke", "green")
                        .style("stroke-width", "3")
                        .style("opacity", "0.9")
                })

                //check if previous id is outcome value
                id_hash = "#_" + $("#model-analysis-outcome").val()
                if (id_hash !== undefined) {
                    d3.select(id_hash).select("rect")
                        .style("stroke", "yellow")
                        .style("stroke-width", "3")
                }

                // update current id to new color 
                id_hash = "#_" + current_id
                if (id_hash !== undefined) {
                    d3.select(id_hash).select("rect")
                        .style("stroke", "#5D3A9B")
                        .style("stroke-width", "3")
                        .style("opacity", "0.9")
                }
            }
        } catch (exception) {
            console.log("Update treatment select exception ", exception)
        }
    }

    /**
     * 
     * @param {*} container 
     * @returns 
     */
    function addTreatmentLabel(container) {
        // console.log("@addTreatmentLabel for MODEL ANALYSIS")
        let treatment = createSubContainer()
        $("<label />", {
            text: "Treatments"
        }).attr("width", "auto").attr("margin-left", "10px").attr("margin-top", "10px").appendTo(treatment)
        let treatment_div = $("<div />", {
        }).attr("margin-left", "10px").appendTo(treatment)
        // treatment.attr("id", "treatment-container")
        treatment.appendTo(container)
        $('<ol>', { id: "treatment-list" }).appendTo(treatment_div)
            .css({
                "min-height": "150px",
                "max-height": "350px",
                // "min-width": "450px",
                // "margin-top": "1em",
                "margin-left": "0.25em",
            })
            .editableList({
                addItem: function (container, i, opt) {
                    // console.log(container, i, opt)
                    var prop = opt;
                    container.css({
                        overflow: "hidden",
                        whiteSpace: "nowrap",
                    });
                    // Create Row append to container
                    var row = $("<div/>").appendTo(container);
                    var propertyName = $("<select/>", {
                    }).css("width", "75%")
                        .appendTo(row)
                    for (let node in nodes) {
                        if (nodes[node] !== undefined) {
                            node = nodes[node]
                            if (node.type === "causeeffect") {
                                $("<option/>", {
                                    id: node.id,
                                    value: node.name,
                                    text: node.name
                                }).appendTo(propertyName)
                            }
                        }
                    }
                    // add current value to set
                    treatments = { ...treatments, [i]: propertyName.children(":selected").attr("id") }
                    propertyName.on("change", async (event) => {
                        updateTreatmentSelect(treatments[i], propertyName.children(":selected").attr("id"), "treatment")
                        treatments[i] = propertyName.children(":selected").attr("id")
                        updateTreatments($("#ace-treatment-list"))

                    })
                    updateTreatments($("#ace-treatment-list"))
                    updateTreatmentSelect(propertyName.children(":selected").attr("id"), propertyName.children(":selected").attr("id"), "treatment")
                },
                removeItem: async function (index) {
                    treatments = {}
                    let items = treatmentList.editableList("items")
                    // find item not in treatment list
                    Array.from(items).forEach(async (item, index) => {
                        let value = item.find("select").val()
                        treatments = { ...treatments, [index]: nn[value] }
                    })
                    updateTreatments($("#ace-treatment-list"))
                },
                removable: true,
                sortable: true,
            })
        return
    }

