    /**
     * Iterates through the causal inference analysis types to build the components for each section 
     * @param {object} causalAnalysisStack - node-red stack container to add various causal inference capabilities
     */
    async function initializeCausalAnalysisFunctionality() {
        // iterate first through the functionality for the specific strategy
        for await (let option of Object.keys(causal_analysis_types)) {
            await causalStrategyManager.addStrategy(new CausalAnalysisFunctionality(option, causal_analysis_types[option]))
        }
        for await (let option of Object.keys(causal_analysis_preconfig)) {
            await causalStrategyManager.addStrategy(new CausalAnalysisFunctionality(option, causal_analysis_preconfig[option]))
        }
    }

    /**
     * 
     * @param {*} causalAnalysisStack 
     */
    async function buildCausalAnalysisContainers(causalAnalysisStack) {
        // console.log("@buildCausalAnalysisContainers", causalAnalysisStrategyType)
        for await (let option of CausalAnalysisStrategies[causalAnalysisStrategyType]["options"]) {
            let strategy = causalStrategyManager.getStrategy(option)
            if (strategy._name !== "fcm") {
                await addCausalAnalysisContainer(causalAnalysisStack, option)
                if (strategy !== undefined || strategy !== null) {
                    strategy.build_container()
                }
            }
        }
    }

    async function updateCausalAnalysisContainersSelect() {
        for await (let option of CausalAnalysisStrategies[causalAnalysisStrategyType]["options"]) {
            let strategy = causalStrategyManager.getStrategy(option)
            if (strategy._name !== "fcm") {
                if (strategy !== undefined || strategy !== null) {
                    strategy._handlers["handleExecutableChanges"]()
                }
            }
        }
    }
    async function updateViewICC() {
        try {
            if (RED.causeway.causalAnalysisStrategyType === "mean") {
                let root_node = ""
                if (nodes !== null) {
                    let root_found = false
                    // find a root node
                    for await (let node of nodes) {
                        console.log(node)
                        if (root_found === false) {
                            if (!Object.keys(parent_child).includes(node.id)) {
                                console.log(node.id, node.name)
                                root_node = node.id
                                root_found = true
                            }
                        } else {
                            console.log("breaking for await loop")
                            break;
                        }
                    }
                    if (root_found) {
                        // let evt = new MouseEvent("mousedown", {
                        //     button: 1
                        // });
                        // console.log("MOUSE EVENT ", evt)
                        // // The way to dispatch the event using d3
                        // console.log(d3.select($("#_" + root_node).find("rect")[0]).node())
                        // d3.select($("#_" + root_node).find("rect")[0]).node().dispatchEvent(evt);

                        let selectedNode = RED.nodes.convertNode(RED.nodes.node(root_node))
                        let parents = parent_child[selectedNode.id] !== undefined ? parent_child[selectedNode.id] : []
                        await $.ajax({
                            url: "causeway/clearICC",
                            type: "POST",
                            data: JSON.stringify({ "parents": parents, "nodeID": selectedNode.id, "nn": nn, "nodeName": selectedNode.name, "activeWorkspace": activeWorkspace }),
                            contentType: "application/json; charset=utf-8",
                            success: async function (resp) {
                                console.log("successfully updated ICC")
                                // await updateICCStatusText(selectedNode)
                                RED.view.reveal(selectedNode.id, true)
                            },
                            error: function (jqXHR, textStatus, errorThrown) {
                                console.log("ERROR THROWN ", errorThrown)
                            }
                        })
                    }
                }
            }
        } catch (exception) {
            console.log("update view ICC exception ", exception)
        }
        return
    }

