    /**
     * 
     */
    async function create_causeway_tab() {
        try {
            content = $("<div>").css({ "position": "relative", "height": "100%" })
            content.className = "red-ui-sidebar-info"
            // add causway sidebar to node-red sidebar
            RED.sidebar.addTab({
                id: "cm",
                label: "CAUSEWAY",
                name: "CAUSEWAY",
                iconClass: "fa fa-bolt",
                action: "core:show-cm-tab",
                content: content,
                pinned: true,
                enableOnEdit: true,
            })

            // create causweay-sidebar container
            $("<div>", { id: "causeway-sidebar" }).css({ "position": "relative", "height": "100%" }).appendTo(content)
            causeway_sidebar_tabs = RED.tabs.create({
                element: $('<ul id="causeway-content-tabs"></ul>').appendTo("#causeway-sidebar"),
                onchange: function (tab) {
                    $("#causeway-sidebar-content").children().hide();
                    if (tab.onchange) {
                        tab.onchange.call(tab);
                    }
                    $(tab.wrapper).show();
                    if (tab.toolbar) {
                        $(tab.toolbar).show();
                    }
                },
                onremove: function (tab) {
                    $(tab.wrapper).hide();
                    if (tab.onremove) {
                        tab.onremove.call(tab);
                    }
                },
                // minimumActiveTabWidth: 70,
                collapsible: true,
                onreorder: function (order) {
                    RED.settings.set("editor.sidebar.order", order);
                },
                order: RED.settings.get("causeway.content.tabs", ["gpt", "ma", "ca"])
            });

            $('<div id="causeway-sidebar-content" style="height:100%"></div>').appendTo("#causeway-sidebar");

            let causalQueryContainer;
            try {
                // Prompt Container
                causalQueryContainer = $("<div/>").css({
                    "overflow-y": "scroll",
                    "height": "inherit",
                }).attr("id", "causal-query-container")
                await createCausalQueryForm(causalQueryContainer)
            } catch (exception) {
                console.log("Error while loading create causeway tab")
            }

            // PANEL 1: Model Analysis
            var maPanel = $("<div>").css({
                "overflow-y": "scroll",
                "height": "calc(100%)"
            })
            let maPanelHeader = $("<div/>", { class: "red-ui-palette-header red-ui-info-header" }).css({
                "flex": "0 0 auto"
            }).appendTo(maPanel)
            let maPanelHeaderLabel = $("<span/>").appendTo(maPanelHeader)
            maPanelHeaderLabel.text("Model Analysis")
            var maContainer = $("<div/>").css({ "flex": "1 1 auto", "overflow-y": "scroll" })
                .appendTo(maPanel)
                .attr("id", "ma-container");

            // PANEL 2: Causal Analysis 
            var caPanel = $("<div/>").css({ "overflow-y": "scroll", "height": "calc(100%)" })
            let caPanelHeader = $("<div/>", { class: "red-ui-palette-header red-ui-info-header" })
                .css({ "flex": "0 0 auto" })
                .appendTo(caPanel);
            let caPanelHeaderLabel = $("<span/>").appendTo(caPanelHeader);
            caPanelHeaderLabel.text("Causal Analysis");
            let caContainer = $("<div>").css({ "flex": "1 1 auto", "overflow-y": "scroll" })
                .appendTo(caPanel)
                .attr("id", "ca-container");
            await loadCausewayTabs(causalQueryContainer, maContainer, caContainer)
        } catch (exception) {
            throw exception
        }
    }

