    /**
     * 
     * @param {*} nodes 
     * @returns 
     */
    async function findModelType(nodes) {
        let ces = 0
        let kns = 0
        let type = "KM"
        try {
            for (let node of nodes) {
                node = node.__node__
                if (node.type === "causeeffect" || node.type === "probability") { ces += 1 }
                if (node.type === "entity" || node.type === "attribute" || node.type === "relation" || node.type === "rule") { kns += 1 }
            }
            console.log(`kns: ${kns} ; ces: ${ces} `)
            type = kns >= ces ? "KM" : "CM"
            type = kns === ces ? "NA" : type
            return type
        } catch (exception) {

            for (let node of nodes) {
                if (node.type === "causeeffect" || node.type === "probability") { ces += 1 }
                if (node.type === "entity" || node.type === "attribute" || node.type === "relation" || node.type === "rule") { kns += 1 }
            }
            // console.log(`exception: kns: ${kns}; ces: ${ces} `)
            type = kns >= ces ? "KM" : "CM"
            type = kns === ces ? "NA" : type
            return type
        }
    }
