    /**
     * 
     */
    async function updateTabs() {
        let prefix = "[ displayTabs ]"
        try {
            try {
                if (activeWorkspace !== 0) {
                    let modelType = await findModelType(nodes)
                    let tabs = new Set(causeway_sidebar_tabs.listTabs())
                    // if no nodes are present, offer the option to have causal discovery from data uploaded
                    // need the option to add a tab 
                    if (modelType !== "CM") {
                        let keepTab = ""
                        if (modelType === "KM") {
                            if (nodes.length > 0) {
                                await addCausalDiscoveryTab()
                                await causeway_sidebar_tabs.activateTab(placeholder_options["causeway-discovery"].id)
                                keepTab = placeholder_options["causeway-discovery"].id
                            }
                        } else {
                            if (nodes.length > 0) {
                                await causeway_sidebar_tabs.addTab(placeholder_options["temp"])
                                await causeway_sidebar_tabs.activateTab(placeholder_options["temp"].id)
                                keepTab = placeholder_options["temp"].id
                            }
                        }
                        // cant remove all tabs without one being present first
                        await removeTabs(tabs, keepTab)
                    } else {
                        await addTabs(tabs)
                        await removeTab(causeway_sidebar_tabs, "causeway-not-causal")
                        await removeTab(causeway_sidebar_tabs, "causeway-discovery")
                    }
                }
            } catch (exception) {
                console.log(`${prefix} Displaying tabs exception`, exception)
            }
        } catch (exception) {
            console.log()
        }
    }

