    async function queryLinkColor(node) {
        try {
            let _fn = `~~queryLinkColor~~`
            let inputs = []
            // get the parents of parents of the current node
            let parents = parent_child[node.id]
            for (let i = 0; i < parents.length; i++) {
                let parentnode = await RED.nodes.node(parents[i])
                if (parentnode.hasOwnProperty("props")) {
                    for await (let prop of parentnode["props"]) {
                        if (prop.hasOwnProperty("p")) {
                            if (prop["p"] === "input") {
                                // get concept node 
                                let conceptNode = await RED.nodes.node(prop.v)
                                let attributeType = ""
                                if (conceptNode.hasOwnProperty("props")) {
                                    for await (let conceptprop of conceptNode["props"]) {
                                        if (conceptprop.v === prop.attribute) {
                                            attributeType = conceptprop.vt
                                        }
                                    }
                                }
                                // find specific attribute 
                                // add the type of the attribute to dictionary below
                                inputs.push({
                                    "kgId": prop.vt,
                                    "conceptName": await RED.nodes.node(prop.v).name,
                                    "attributeName": prop.attribute,
                                    "nodeName": parentnode.name,
                                    "effectName": node.name,
                                    "attributeType": attributeType
                                })
                            }
                        }
                    }
                }
            }
            console.log(`${_fn} inputs `, inputs)
            if (inputs.length > 0) {
                try {
                    // aws/host.docker.internal implementation
                    let effectMinMax = await $.ajax({
                        headers: {
                            Accept: "text/html; application/json",
                        },
                        cache: false,
                        url: "causeway/queryLinkColor",
                        type: "GET",
                        timeout: 0,
                        data: {
                            "inputs": inputs,
                        },
                        success: async function (json) {
                            
                            console.log("at success")
                        },
                        error: async function (err) {
                            console.log("error ajax causeway/queryLinkColor", err)
                        },
                        complete: async function () {
                        }
                    })

                    effectMinMax = JSON.parse(effectMinMax[node.name])
                    // console.log("effectMinMax", effectMinMax)
                    // caculcate edge color from min and max

                    let min = effectMinMax["min"][0][0]
                    let max = effectMinMax["max"][0][0]

                    let edgeColor = min < max ? "green" : "red"
                    edgeColor = min === max ? "grey" : edgeColor
                    return edgeColor
                } catch (exception) {
                    console.log("queryLinkColor exception", exception)
                    throw exception
                }
            }
            // i need the knowledge graph its coming from
            //  the entity name
            // the attribute of the entity
        } catch (exception) {
            console.log(exception)
            throw exception
        }
    }

